WITH parsed AS (SELECT id, service, log_ts, level, latency_ms, payload_json, COALESCE(context['version'], 'unknown') AS version_or_default, COALESCE(context['trace'], 'none') AS trace_or_default, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, service, MAX(log_ts) AS last_log_ts, STDDEV_SAMP(latency_ms) AS latency_ms_stddev, BIT_AND(latency_ms) AS latency_ms_bit_and, MIN(log_ts) AS first_seen, SIZE(COLLECT_SET(service)) AS num_services FROM parsed GROUP BY 1, 2 HAVING num_services > 1
